import type { ComponentProps } from "react";

import { IconChevronDown, IconClock, IconMail, IconNavigation, IconPhone, IconPin } from "@rhs-ui/icons";
import { canTellStatus, fill, LABELS, type LocalBusinessLabels, type OpeningDay } from "@rhs-ui/marketing/local-business-hero/hours";
import { OpenStatus, TodayHours, WeekHours } from "@rhs-ui/marketing/local-business-hero/status";
import { Button } from "@rhs-ui/primitives/button";
import { cn } from "@/lib/utils";

export type { LocalBusinessLabels, OpeningDay } from "@rhs-ui/marketing/local-business-hero/hours";

export interface LocalBusinessImage {
  /** The address of the picture. A data: URI works too. */
  src: string;
  /** What the picture shows: "The shopfront on Kerkstraat, with bikes in the window". */
  alt: string;
  /** Intrinsic size, so the browser can reserve the space. */
  width?: number;
  height?: number;
  /** Candidate files for the browser to choose from, as in an <img srcset>. */
  srcSet?: string;
  /** How wide the picture is shown, as in an <img sizes>. Set it with `srcSet`. The default is half the screen from lg, the whole width below. */
  sizes?: string;
  /** A tiny picture, as a data: URI of a few hundred bytes, that stands in blurred while the real one loads. */
  blurDataUrl?: string;
}

export interface LocalBusinessHeroProps extends Omit<ComponentProps<"section">, "title" | "children"> {
  /** The name's element: "h2" inside a page that has its own h1 (the default), "h1" when the hero opens the page. */
  titleAs?: "h1" | "h2";
  /** The business's name. */
  name: string;
  /** One line on what it does. */
  tagline?: string;
  /** The number as people read it: "024 123 45 67". The call button and its tel: link are made from it, so a phone dials it with one tap. */
  phone: string;
  /** An email address. It becomes a mailto: link in the card. */
  email?: string;
  /** The address, as lines ("Kerkstraat 14", "6511 AB Nijmegen") or as one string. */
  address: string | readonly string[];
  /** The week as seven days in the shape of OpeningHours: a name and the hours, null for a closed day. The status is worked out from the hours text, written as 24-hour times: "09:00 to 18:00", or "09:00 to 12:30, 13:30 to 18:00" with a break. Hours it cannot read (12-hour times, fewer than seven days) show the card and the week as written, and no status. */
  hours: readonly OpeningDay[];
  /** Where the directions link leads: a map link for the address. */
  directionsHref: string;
  /** The photo at the top of the card. Leave it out for a card without one. */
  image?: LocalBusinessImage;
  /** The business's own time zone as an IANA name: "Europe/Amsterdam". Required, because "open now" is a statement about the clock where the business is, not where the visitor is. */
  timeZone: string;
  /** Which day `hours` starts on: 1 for Monday (the default), 0 for Sunday. */
  weekStartsOn?: 0 | 1;
  /** A fixed moment to work the status out for, for previews and tests. Leave it out and the visitor's own clock is read in the browser, so the server never prints a stale "Open". */
  now?: Date | string | number;
  /** Words for the fixed text and the status sentences, for a site that is not in English. `{time}`, `{day}` and `{phone}` are filled in. */
  labels?: Partial<LocalBusinessLabels>;
}

/** "+31 (0)24 123 45 67" -> "+31241234567": what a tel: link wants. */
function telOf(phone: string): string {
  return phone.replace(/\(0\)/g, "").replace(/[^\d+]/g, "");
}

/**
 * The front of a local business: its name, whether it is open right now, and
 * a call button, all on the first screen. Beside them a card with a photo, the
 * address in an address element, today's hours and the full week folded into
 * a details element. The status ("Open now, closes 18:00", "Closed now, opens
 * tomorrow 13:00") is worked out in the business's time zone in the browser
 * while the server renders only the hours, so there is never a wrong "Open"
 * flash; the pill holds its place and fades in. Phone and email are real tel:
 * and mailto: links. For shops, garages, salons and practices, where the first
 * question is whether you are open and where you are.
 */
export function LocalBusinessHero({
  titleAs: Title = "h2",
  name,
  tagline,
  phone,
  email,
  address,
  hours,
  directionsHref,
  image,
  timeZone,
  weekStartsOn = 1,
  now,
  labels,
  className,
  ...props
}: LocalBusinessHeroProps) {
  const words = { ...LABELS, ...labels };
  const lines = typeof address === "string" ? [address] : address;
  const clock = { days: hours, timeZone, weekStartsOn, now, labels: words };
  // Decided here, on the server: hours the block cannot read (12-hour times, fewer than seven days) never give a status, so no pill is drawn and no space is kept for one.
  const tells = canTellStatus(hours, timeZone);

  return (
    <section data-slot="local-business-hero" className={cn("grid grid-cols-1 items-center gap-12 py-16 sm:py-20 lg:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)] lg:gap-16", className)} {...props}>
      <div className="min-w-0">
        <Title className="text-4xl leading-[1.04] font-medium tracking-[-0.04em] text-balance sm:text-5xl lg:text-6xl">{name}</Title>
        {tagline ? <p className="mt-5 max-w-md text-base leading-relaxed text-pretty text-muted-foreground sm:text-lg">{tagline}</p> : null}
        {tells ? <OpenStatus {...clock} className="mt-7" /> : null}
        <div className={cn("flex flex-wrap items-center gap-3", tells ? "mt-5" : "mt-8")}>
          <Button asChild size="lg" className="max-sm:grow">
            <a href={`tel:${telOf(phone)}`}>
              <IconPhone />
              {fill(words.call, { phone })}
            </a>
          </Button>
          <Button asChild size="lg" variant="outline" className="max-sm:grow">
            <a href={directionsHref}>
              <IconNavigation />
              {words.directions}
            </a>
          </Button>
        </div>
      </div>

      <div data-slot="local-business-hero-card" className="min-w-0 overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm">
        {image ? (
          <div className="relative aspect-[16/9] overflow-hidden border-b border-border bg-muted">
            {image.blurDataUrl ? <span aria-hidden="true" className="absolute inset-0 scale-110 bg-cover bg-center blur-xl" style={{ backgroundImage: `url("${image.blurDataUrl}")` }} /> : null}
            {/* eslint-disable-next-line @next/next/no-img-element -- framework-neutral; the picture is any URL or data URI */}
            <img
              src={image.src}
              alt={image.alt}
              width={image.width}
              height={image.height}
              srcSet={image.srcSet}
              sizes={image.sizes ?? "(min-width: 1024px) 48vw, 100vw"}
              loading="eager"
              fetchPriority="high"
              decoding="async"
              className="absolute inset-0 size-full object-cover"
            />
          </div>
        ) : null}
        <div className="divide-y divide-border">
          <div className="flex gap-4 px-5 py-4">
            <IconPin className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
            <address className="text-sm leading-relaxed not-italic">
              <span className="sr-only">{words.address}: </span>
              {lines.map((line) => (
                <span key={line} className="block">
                  {line}
                </span>
              ))}
            </address>
          </div>
          {hours.length ? (
            <div className="flex gap-4 px-5 py-4">
              <IconClock className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
              <TodayHours {...clock} />
            </div>
          ) : null}
          {email ? (
            <div className="flex gap-4 px-5 py-4">
              <IconMail className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
              <a href={`mailto:${email}`} className="min-w-0 rounded-sm text-sm underline-offset-4 outline-none [overflow-wrap:anywhere] hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/40">
                {email}
              </a>
            </div>
          ) : null}
          {hours.length ? (
            <details className="group/week">
              <summary className="flex cursor-pointer list-none items-center justify-between gap-4 px-5 py-4 text-sm font-medium transition-colors duration-150 outline-none select-none hover:bg-muted/60 focus-visible:ring-[3px] focus-visible:ring-ring/40 focus-visible:ring-inset motion-reduce:transition-none [&::-webkit-details-marker]:hidden">
                {words.week}
                <IconChevronDown className="size-4 shrink-0 text-muted-foreground transition-transform duration-200 group-open/week:rotate-180 motion-reduce:transition-none" />
              </summary>
              <div className="px-5 pb-5">
                <WeekHours {...clock} />
              </div>
            </details>
          ) : null}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useSyncExternalStore } from "react";

import { describeStatus, statusAt, toTimestamp, zonedClock, type LocalBusinessLabels, type OpeningDay } from "@rhs-ui/marketing/local-business-hero/hours";
import { Badge } from "@rhs-ui/primitives/badge";
import { cn } from "@/lib/utils";

/* One clock for every part of the block: a shared timer that ticks while any of them is on the page. */
const listeners = new Set<() => void>();
let timer: ReturnType<typeof setInterval> | undefined;

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  timer ??= setInterval(() => listeners.forEach((notify) => notify()), 30_000);
  return () => {
    listeners.delete(listener);
    if (!listeners.size && timer) {
      clearInterval(timer);
      timer = undefined;
    }
  };
}

/** The visitor's clock, rounded down to the minute so it only changes when the answer can. */
const readMinute = (): number | null => Math.floor(Date.now() / 60_000) * 60_000;
/** The server has no visitor and no clock to trust: it renders the hours and leaves the status to the browser. */
const readNothing = (): number | null => null;

export interface BusinessClockProps {
  days: readonly OpeningDay[];
  timeZone: string;
  weekStartsOn: 0 | 1;
  /** A fixed moment, for previews and tests. Without it the visitor's own clock is read, after hydration. */
  now?: Date | string | number;
  labels: LocalBusinessLabels;
  className?: string;
}

function useBusinessClock({ days, timeZone, weekStartsOn, now }: Pick<BusinessClockProps, "days" | "timeZone" | "weekStartsOn" | "now">) {
  const minute = useSyncExternalStore<number | null>(subscribe, readMinute, readNothing);
  const at = now === undefined ? minute : (toTimestamp(now) ?? null);
  const clock = at === null ? null : zonedClock(at, timeZone, weekStartsOn);
  return { clock, status: clock ? statusAt(days, clock) : null };
}

/**
 * The open-or-closed line. It is worked out in the business's time zone in
 * the browser, so the server never prints a stale "Open"; until then the pill
 * holds its place, empty and hidden from assistive technology, and fades in.
 */
export function OpenStatus({ labels, className, ...clock }: BusinessClockProps) {
  const { status } = useBusinessClock(clock);
  const text = status ? describeStatus(status, labels) : null;
  return (
    <p data-slot="local-business-hero-status" className={className}>
      <Badge variant="outline" aria-hidden={text ? undefined : true} className={cn("h-8 gap-2.5 px-3.5 text-sm transition-opacity duration-300 motion-reduce:transition-none", text ? "opacity-100" : "opacity-0")}>
        <span aria-hidden="true" className={cn("size-2 shrink-0 rounded-full", status?.state === "open" ? "bg-foreground" : "border border-muted-foreground")} />
        {text ?? "\u00a0"}
      </Badge>
    </p>
  );
}

/** Today's hours in the card: the word "Today" and the day's opening text, again only once the browser knows the day. */
export function TodayHours({ days, labels, className, ...clock }: BusinessClockProps) {
  const today = useBusinessClock({ days, ...clock }).clock?.today;
  const day = today === undefined ? undefined : days[today];
  return (
    <p data-slot="local-business-hero-today" className={cn("flex flex-wrap items-baseline gap-x-3 text-sm", className)}>
      <span className="font-medium">{labels.today}</span>
      <span className={cn("tabular-nums transition-opacity duration-300 motion-reduce:transition-none", day ? "opacity-100" : "opacity-0", !day?.hours && "text-muted-foreground")}>
        {day ? (day.hours ?? labels.closedDay) : "\u00a0"}
      </span>
    </p>
  );
}

/**
 * The whole week, with today marked once the browser knows which day it is.
 * It is the block's own list rather than the OpeningHours primitive, whose
 * "Closed", "(today)" and landmark name are fixed English: here every word is
 * one of the block's labels, and the details element above it is the only name.
 */
export function WeekHours({ days, labels, ...clock }: BusinessClockProps) {
  const today = useBusinessClock({ days, ...clock }).clock?.today;
  return (
    <dl data-slot="local-business-hero-week" className="-mx-2 mt-4 grid gap-1.5 text-sm">
      {days.map((day, index) => (
        <div key={day.day} className={cn("flex justify-between gap-4 rounded-md px-2 py-1", index === today && "bg-muted font-medium")}>
          <dt>
            {day.day}
            {index === today ? <span className="sr-only"> ({labels.today})</span> : null}
          </dt>
          <dd className={cn("tabular-nums", !day.hours && "text-muted-foreground")}>{day.hours ?? labels.closedDay}</dd>
        </div>
      ))}
    </dl>
  );
}

import type { OpeningDay } from "@rhs-ui/primitives/opening-hours";

export type { OpeningDay };

export interface LocalBusinessLabels {
  /** Open, with the closing time: "Open now, closes {time}". */
  open: string;
  /** Open, in the last hour before closing: "Closing soon, at {time}". */
  closingSoon: string;
  /** Open around the clock, so there is no closing time to give. */
  always: string;
  /** Closed, and opening later today: "Closed now, opens {time}". */
  opensToday: string;
  /** Closed, and opening tomorrow: "Closed now, opens tomorrow {time}". */
  opensTomorrow: string;
  /** Closed, and opening on another day: "Closed now, opens {day} {time}". The day is the name you gave it in `hours`. */
  opensLater: string;
  /** Closed, and nothing opens in the week. */
  closed: string;
  /** A day without opening times, in today's line and in the week's list. */
  closedDay: string;
  /** The word before today's hours in the card, and the mark read after today's name in the week. */
  today: string;
  /** The call button: "Call {phone}". */
  call: string;
  /** The directions button. */
  directions: string;
  /** The summary of the folded week. */
  week: string;
  /** Read before the address by a screen reader. */
  address: string;
}

export const LABELS: LocalBusinessLabels = {
  open: "Open now, closes {time}",
  closingSoon: "Closing soon, at {time}",
  always: "Open around the clock",
  opensToday: "Closed now, opens {time}",
  opensTomorrow: "Closed now, opens tomorrow {time}",
  opensLater: "Closed now, opens {day} {time}",
  closed: "Closed",
  closedDay: "Closed",
  today: "Today",
  call: "Call {phone}",
  directions: "Get directions",
  week: "Opening hours this week",
  address: "Address",
};

/** Fills the `{name}` holes of a label. */
export function fill(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (_, key: string) => values[key] ?? "");
}

/** Where the business's clock stands: the day (an index into `hours`) and the minutes since midnight. */
export interface Clock {
  today: number;
  minutes: number;
}

export type BusinessStatus =
  | { state: "open"; closesAt?: string; soon: boolean }
  | { state: "closed"; opens?: { when: "today" | "tomorrow" | "later"; day: string; time: string } };

const DAY = 1440;
const WEEK = 7 * DAY;
const WEEKDAYS: Record<string, number> = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
const formatters = new Map<string, Intl.DateTimeFormat>();

/** Any way a moment is handed in, as milliseconds; undefined when it is not a date at all. */
export function toTimestamp(value: Date | string | number | undefined): number | undefined {
  if (value === undefined) return undefined;
  const time = value instanceof Date ? value.getTime() : typeof value === "number" ? value : Date.parse(value);
  return Number.isNaN(time) ? undefined : time;
}

/**
 * What the wall clock in the business's own time zone says at that moment.
 * The names of the day are only read back as parts here, in a fixed locale,
 * never shown. A time zone the browser does not know gives null, and the
 * block then says nothing about the status rather than guess.
 */
export function zonedClock(at: number, timeZone: string, weekStartsOn: 0 | 1 = 1): Clock | null {
  try {
    let format = formatters.get(timeZone);
    if (!format) {
      format = new Intl.DateTimeFormat("en-US", { timeZone, weekday: "short", hour: "2-digit", minute: "2-digit", hourCycle: "h23" });
      formatters.set(timeZone, format);
    }
    const parts = format.formatToParts(new Date(at));
    const part = (type: string) => parts.find((entry) => entry.type === type)?.value ?? "";
    const weekday = WEEKDAYS[part("weekday")];
    const hour = Number(part("hour")) % 24;
    const minute = Number(part("minute"));
    if (weekday === undefined || Number.isNaN(hour) || Number.isNaN(minute)) return null;
    return { today: (weekday - weekStartsOn + 7) % 7, minutes: hour * 60 + minute };
  } catch {
    return null;
  }
}

const RANGE = /(\d{1,2})[:.](\d{2})\s*(?:to|until|till|tot|-|–|—)\s*(\d{1,2})[:.](\d{2})/gi;

/**
 * One day's opening text as ranges of minutes: [] for a closed day, and
 * undefined for text with no times in it ("By appointment"), which nothing
 * can be worked out from.
 */
export function parseDay(hours: string | null): readonly (readonly [number, number])[] | undefined {
  if (hours === null || /^\s*closed\s*$/i.test(hours)) return [];
  const ranges: (readonly [number, number])[] = [];
  for (const match of hours.matchAll(RANGE)) {
    const [from, to] = [Number(match[1]) * 60 + Number(match[2]), Number(match[3]) * 60 + Number(match[4])];
    if (Number(match[2]) < 60 && Number(match[4]) < 60 && from <= DAY && to <= DAY) ranges.push([from, to]);
  }
  return ranges.length ? ranges : undefined;
}

/**
 * Can this week ever give a status? It takes seven days, a time zone the
 * runtime knows and hours it can read: at least one day with times in it, or
 * a week where every day is plainly closed. The server asks this while
 * rendering, so a week that never will (12-hour times, six days, a misspelt
 * zone) leaves no empty pill and no blank band behind it. A single day it
 * cannot read ("By appointment") only hides the pill on that day.
 */
export function canTellStatus(days: readonly OpeningDay[], timeZone: string): boolean {
  if (days.length !== 7 || zonedClock(0, timeZone) === null) return false;
  const parsed = days.map((day) => parseDay(day.hours));
  return parsed.some((ranges) => ranges?.length) || parsed.every((ranges) => ranges !== undefined);
}

/** 18:00 for 1080. An end that falls exactly on midnight reads 24:00, a start there reads 00:00. */
function clockText(minutes: number, closing = false): string {
  const whole = closing && minutes > 0 && minutes % DAY === 0 ? DAY : minutes % DAY;
  return `${String(Math.floor(whole / 60)).padStart(2, "0")}:${String(whole % 60).padStart(2, "0")}`;
}

/**
 * Is the business open at this moment, and if not, when does it open next?
 * The week has to be seven days; a night that runs past midnight carries
 * into the next day, back-to-back days are one long opening, and a day
 * whose text holds no times makes today's answer unknown (null).
 */
export function statusAt(days: readonly OpeningDay[], clock: Clock): BusinessStatus | null {
  if (days.length !== 7) return null;
  const parsed = days.map((day) => parseDay(day.hours));
  if (parsed[clock.today] === undefined) return null;
  const now = clock.today * DAY + clock.minutes;

  const week: { start: number; end: number }[] = [];
  parsed.forEach((ranges, day) => {
    for (const [from, to] of ranges ?? []) week.push({ start: day * DAY + from, end: day * DAY + (to > from ? to : to + DAY) });
  });
  // The week is laid out three times so an opening that crosses either end of it joins the one beside it.
  const spans = [-WEEK, 0, WEEK].flatMap((shift) => week.map((span) => ({ start: span.start + shift, end: span.end + shift }))).sort((a, b) => a.start - b.start);
  const merged: { start: number; end: number }[] = [];
  for (const span of spans) {
    const last = merged[merged.length - 1];
    if (last && span.start <= last.end) last.end = Math.max(last.end, span.end);
    else merged.push({ ...span });
  }

  const current = merged.find((span) => span.start <= now && now < span.end);
  if (current) {
    if (current.end - current.start > WEEK) return { state: "open", soon: false };
    return { state: "open", closesAt: clockText(current.end, true), soon: current.end - now <= 60 };
  }
  const next = merged.find((span) => span.start > now);
  if (!next) return { state: "closed" };
  const absolute = Math.floor(next.start / DAY);
  const offset = absolute - clock.today;
  return {
    state: "closed",
    opens: { when: offset === 0 ? "today" : offset === 1 ? "tomorrow" : "later", day: days[((absolute % 7) + 7) % 7]?.day ?? "", time: clockText(next.start) },
  };
}

/** The status as a sentence, from your labels. */
export function describeStatus(status: BusinessStatus, labels: LocalBusinessLabels): string {
  if (status.state === "open") return status.closesAt ? fill(status.soon ? labels.closingSoon : labels.open, { time: status.closesAt }) : labels.always;
  if (!status.opens) return labels.closed;
  const { when, day, time } = status.opens;
  return fill(when === "today" ? labels.opensToday : when === "tomorrow" ? labels.opensTomorrow : labels.opensLater, { day, time });
}
